class TestPtyCreateAndEcho:
    def test_create_and_echo(self, pty_session):
        """Create PTY, run echo, verify output."""
        output_chunks = []

        def on_data(data: bytes):
            output_chunks.append(data)

        handle = pty_session.pty.create(on_data=on_data)
        assert handle.pty_session_id
        assert handle.is_connected

        time.sleep(1)

        handle.send_input(b"echo 'PTY_TEST_OK_98765'\r")
        time.sleep(2)

        combined = b"".join(output_chunks).decode("utf-8", errors="replace")
        assert "PTY_TEST_OK_98765" in combined

        handle.disconnect()


class TestPtyCtrlC:
    def test_ctrl_c(self, pty_session):
        """Send Ctrl+C to interrupt a running command."""
        output_chunks = []

        def on_data(data: bytes):
            output_chunks.append(data)

        handle = pty_session.pty.create(on_data=on_data)
        time.sleep(1)

        handle.send_input(b"sleep 100\r")
