class TestPtyConnect:
    def test_disconnect_and_reconnect(self, pty_session):
        """Disconnect then reconnect, verify I/O works."""
        output1 = []
        handle1 = pty_session.pty.create(
            on_data=lambda d: output1.append(d)
        )
        time.sleep(1)

        handle1.send_input(b"echo 'BEFORE_DISCONNECT'\r")
        time.sleep(1)

        pty_id = handle1.pty_session_id
        handle1.disconnect()
        assert not handle1.is_connected

        output2 = []
        handle2 = pty_session.pty.connect(
            pty_id, on_data=lambda d: output2.append(d)
        )
        assert handle2.is_connected

        handle2.send_input(b"echo 'AFTER_RECONNECT'\r")
        time.sleep(2)

        combined = b"".join(output2).decode("utf-8", errors="replace")
        assert "AFTER_RECONNECT" in combined

        handle2.disconnect()


class TestPtyExit:
    def test_exit_event(self, pty_session):
        """Send exit, verify pty.exit event and wait() returns exit code 0."""
        handle = pty_session.pty.create()
        time.sleep(1)

        handle.send_input(b"exit\r")
        exit_code = handle.wait(timeout_s=10)
        assert exit_code == 0
        assert handle.exit_code == 0
        assert not handle.is_connected


